package studio.manga.config; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; import studio.manga.identity.UnauthorizedException;
@RestControllerAdvice public class ApiErrors { @ExceptionHandler(NoSuchElementException.class) ResponseEntity<Map<String,String>> missing(NoSuchElementException e){return ResponseEntity.status(HttpStatus.NOT_FOUND).body(Map.of("message",e.getMessage()));} @ExceptionHandler(UnauthorizedException.class) ResponseEntity<Map<String,String>> unauthorized(UnauthorizedException e){return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("message",e.getMessage()));} @ExceptionHandler(IllegalArgumentException.class) ResponseEntity<Map<String,String>> invalid(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));} }
